pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    bytes32 constant DEFAULT_ADMIN_ROLE = 0x00;

    function setUp() public { c = new Size(); }

    function testFuzz_property(bytes32 role, address account) public {
        // No roles have been granted on the freshly deployed contract, so for
        // ANY (role, account) the membership check must be false. The buggy
        // version returns true unconditionally.
        assertTrue(!c.hasRole(role, account));
    }
}
